<?php require 'config.php';require_login();if(is_admin()){header('Location: admin.php');exit;}$s=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC");$s->execute([$_SESSION['user_id']]);$orders=$s->fetchAll();$page_title='My orders';require 'header.php';?><section class="wrap"><h1>My orders</h1><?php if(isset($_GET['placed'])):?><div class="notice">Your order has been placed successfully.</div><?php endif;?><?php if(!$orders):?><p class="muted">You haven't placed an order yet.</p><?php else:?><table class="table"><tr><th>Order</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th></tr><?php foreach($orders as $o):?><tr><td>#<?=$o['id']?></td><td><?=e($o['created_at'])?></td><td><?=money($o['total'])?></td><td><?=e($o['payment_method'])?></td><td><?=e($o['status'])?></td></tr><?php endforeach;?></table><p class="muted">Order status updates appear here. Live courier GPS tracking requires a courier integration.</p><?php endif;?></section><?php require 'footer.php';?>
